import base64
import os
from pathlib import Path
import subprocess
import sys

os.environ["HF_HOME"] = "/kaggle/working/.cache/huggingface"
subprocess.run(
    [sys.executable, "-m", "pip", "install", "transformers==5.17.0", "peft==0.21.2", "bitsandbytes==0.50.2", "accelerate==1.15.0"],
    check=True,
    timeout=900,
)
os.environ.setdefault("E07_SMOKE", "1")
os.environ.setdefault("E07_FOLD", "1")
worker = base64.b64decode("")
old_reset = b'''    current = model.state_dict()\n    current.update(initial_state)\n    model.load_state_dict(current, strict=True)\n'''
new_reset = b'''    # Restore only trainable LoRA tensors; do not reload bitsandbytes auxiliary state.\n    named_parameters = dict(model.named_parameters())\n    assert set(initial_state).issubset(named_parameters)\n    with torch.no_grad():\n        for name, value in initial_state.items():\n            parameter = named_parameters[name]\n            parameter.copy_(value.to(device=parameter.device, dtype=parameter.dtype))\n'''
assert worker.count(old_reset) == 1
worker = worker.replace(old_reset, new_reset)
Path("/kaggle/working/e07_worker.py").write_bytes(worker)
subprocess.run([sys.executable, "-u", "/kaggle/working/e07_worker.py"], check=True, timeout=27600)
